% runCase1b  Case 1(b), shared latent driver, variants (i) to (iii). GeoC, trajectories and invariant densities.
%
% CALLS     generateCase1Series, estimateGeoC, plotLocalSlopeDiagnostics2x2, estimateInvariantDensity2D,
%           batlow, addPanelLabel
% INPUT     none (records are generated by generateCase1Series('1bi'), ('1bii') and ('1biii'))
% OUTPUT    ResultsCaseIbAll/FigureGeoCCase1bModel1.png to Model3.png, FigureCase1bAllTrajectories.png,
%           FigureCase1bAllInvariantDensities.png, InvOut_Case1b_all.mat and the GeoC tables printed in the command window

clear; close all; clc;
set(groot, 'defaultTextInterpreter', 'latex');
set(groot, 'defaultAxesTickLabelInterpreter', 'latex');
set(groot, 'defaultLegendInterpreter', 'latex');

outDir = 'ResultsCaseIbAll';
if ~exist(outDir, 'dir'), mkdir(outDir); end
betaMax = 1.5;
ids = {'1bi', '1bii', '1biii'};
caseTitles = {'Case 1(b)(i)', 'Case 1(b)(ii)', 'Case 1(b)(iii)'};
d2Opts = {'MinPlateauLength', 10, 'SlopeCVmax', 0.15, 'MaxSlopeDrift', 0.10, 'R2min', 0.98, 'Cmax', 0.20, 'MinPairs', 1000};

%%
Mu = cell(1,3); Beta = cell(1,3); invOut = cell(1,3);
for k = 1:3
    [Mu{k}, Beta{k}] = generateCase1Series(ids{k});
    [T, details] = estimateGeoC(Mu{k}, Beta{k}, 'Subsample', 2500, 'Seed', 2, d2Opts{:});
    disp(caseTitles{k}); disp(T);
    fig = plotLocalSlopeDiagnostics2x2(details);
    exportgraphics(fig, fullfile(outDir, sprintf('FigureGeoCCase1bModel%d.png', k)), 'Resolution', 600);
    close(fig);
    invOut{k} = estimateInvariantDensity2D(Mu{k}, Beta{k}, 'NBins', 100, 'Bounds', [0 0; 1 betaMax]);
end
invOut1 = invOut{1}; invOut2 = invOut{2}; invOut3 = invOut{3};
save(fullfile(outDir, 'InvOut_Case1b_all.mat'), 'invOut1', 'invOut2', 'invOut3');

%%
fig = figure('Color', 'w', 'Units', 'centimeters', 'Position', [1.5 1.5 18.2 17.0], 'Renderer', 'painters');
tl = tiledlayout(fig, 3, 3, 'TileSpacing', 'compact', 'Padding', 'compact');
fontName = 'Arial';
for k = 1:3
    for row = 1:3
        ax = nexttile(tl, (row - 1) * 3 + k);
        switch row
            case 1
                x = Mu{k}(1:end-1); y = Mu{k}(2:end); lim = [0 1];
                xl = '$\mu_n$'; yl = '$\mu_{n+1}$'; xt = 0:0.2:1; yt = 0:0.2:1;
            case 2
                x = Beta{k}(1:end-1); y = Beta{k}(2:end); lim = [0 betaMax];
                xl = '$\beta_n$'; yl = '$\beta_{n+1}$'; xt = 0:0.3:1.5; yt = 0:0.3:1.5;
            case 3
                x = Mu{k}; y = Beta{k}; lim = [];
                xl = '$\mu$'; yl = '$\beta$'; xt = 0:0.2:1; yt = 0:0.3:1.5;
        end
        scatter(ax, x, y, 3, [0.16 0.16 0.16], 'filled', 'MarkerFaceAlpha', 0.42, 'MarkerEdgeColor', 'none');
        if row < 3
            hold(ax, 'on');
            plot(ax, lim, lim, '--', 'Color', [0.65 0.65 0.65], 'LineWidth', 0.8, 'HandleVisibility', 'off');
            hold(ax, 'off');
            xlim(ax, lim); ylim(ax, lim);
        else
            xlim(ax, [0 1]); ylim(ax, [0 betaMax]);
        end
        xticks(ax, xt); yticks(ax, yt);
        xlabel(ax, xl, 'FontName', fontName, 'FontSize', 10);
        ylabel(ax, yl, 'FontName', fontName, 'FontSize', 10);
        set(ax, 'FontName', fontName, 'FontSize', 9.0, 'LineWidth', 0.85, 'TickDir', 'out', ...
            'TickLength', [0.018 0.018], 'Box', 'off', 'Layer', 'top', 'XMinorTick', 'on', 'YMinorTick', 'on');
        axis(ax, 'square'); grid(ax, 'off');
        if row == 1
            title(ax, ['\textbf{' caseTitles{k} '}'], 'FontName', fontName, 'FontSize', 11.5, 'FontWeight', 'normal');
        end
        addPanelLabel(ax, sprintf('(%s)', char('a' + (row - 1) * 3 + k - 1)), -0.24, 0.95, 11);
    end
end
exportgraphics(fig, fullfile(outDir, 'FigureCase1bAllTrajectories.png'), 'Resolution', 600, 'BackgroundColor', 'white');
close(fig);

%%
fig = figure('Color', 'w', 'Units', 'centimeters', 'Position', [2.0 2.0 18.0 19.0], 'Renderer', 'painters');
tl = tiledlayout(fig, 3, 2, 'TileSpacing', 'compact', 'Padding', 'compact');
muColor = [0.20 0.35 0.55]; betaColor = [0.70 0.35 0.20];
axStyle = {'FontName', fontName, 'FontSize', 8.0, 'LineWidth', 0.7, 'TickDir', 'out', 'TickLength', [0.015 0.015], ...
    'Box', 'off', 'Layer', 'top', 'XMinorTick', 'on', 'YMinorTick', 'on'};
for k = 1:3
    axD = nexttile(tl, (k - 1) * 2 + 1);
    contourf(axD, invOut{k}.MU, invOut{k}.BETA, invOut{k}.invariantDensity, 25, 'LineColor', 'none');
    colormap(axD, batlow(256));
    xlabel(axD, '$\mu$', 'FontName', fontName, 'FontSize', 9.5);
    ylabel(axD, '$\beta$', 'FontName', fontName, 'FontSize', 9.5);
    xlim(axD, [0 1]); ylim(axD, [0 betaMax]);
    set(axD, axStyle{:}); grid(axD, 'off'); pbaspect(axD, [1 1 1]);
    cb = colorbar(axD, 'eastoutside');
    cb.Label.String = '$p^*(\mu,\beta)$'; cb.Label.Interpreter = 'latex'; cb.Label.FontSize = 9;
    cb.FontName = fontName; cb.FontSize = 7.0; cb.LineWidth = 0.5; cb.TickDirection = 'out';
    addPanelLabel(axD, sprintf('(%s)', char('a' + 2*k - 2)), -0.24, 0.95, 11);

    axM = nexttile(tl, (k - 1) * 2 + 2);
    yyaxis(axM, 'left');
    hMu = plot(axM, invOut{k}.muVec, invOut{k}.f_mu_marginal, '-', 'Color', muColor, 'LineWidth', 1.5, 'DisplayName', 'Virulence, $\mu$');
    ylabel(axM, '$p^*_{\mu}(\mu)$', 'FontName', fontName, 'FontSize', 9.5);
    axM.YColor = muColor;
    yyaxis(axM, 'right');
    hBeta = plot(axM, invOut{k}.betaVec, invOut{k}.f_beta_marginal, '--', 'Color', betaColor, 'LineWidth', 1.5, 'DisplayName', 'Transmission, $\beta$');
    ylabel(axM, '$p^*_{\beta}(\beta)$', 'FontName', fontName, 'FontSize', 9.5);
    axM.YColor = betaColor;
    xlabel(axM, '$\mu,\ \beta$', 'FontName', fontName, 'FontSize', 9.5);
    xlim(axM, [0 betaMax]);
    set(axM, axStyle{:}); grid(axM, 'off');
    legend(axM, [hMu hBeta], 'Location', 'northoutside', 'Interpreter', 'latex', 'Box', 'off', ...
        'FontName', fontName, 'FontSize', 7.0, 'NumColumns', 2);
    addPanelLabel(axM, sprintf('(%s)', char('a' + 2*k - 1)), -0.24, 0.95, 11);
end
exportgraphics(fig, fullfile(outDir, 'FigureCase1bAllInvariantDensities.png'), 'Resolution', 600, 'BackgroundColor', 'white');
close(fig);
